        }
        cookieHost.setCookie(FQ_ACCOUNT_SITE,webText);changedStore=true;
        if(canRestoreOverlay){store.deleteMemory(key);cleared=true;}
        if(fqAccountAuthSignature(fqAccountCookieText(cookieHost))!==fqAccountAuthSignature(webText))throw new Error('会话回读不一致');
        return true;
    } catch(ignore) {
        if(changedStore)try {
            cookieHost.setCookie(FQ_ACCOUNT_SITE,before);
            if(cleared){store.deleteMemory(key);if(overlay!=null)store.putMemory(key,overlay);}
            if(fqAccountAuthSignature(fqAccountCookieText(cookieHost))!==fqAccountAuthSignature(before))throw new Error('恢复失败');
        }catch(restoreError){throw new Error('官网会话同步失败，原有记录未能恢复，请重新网页登录');}
