        if(!response||typeof response.code!=='function'||typeof response.body!=='function'||Number(response.code())!==200)throw new Error('HTTP');
        json=fqParseJson(String(response.body()),false);
    } catch(ignore) {throw new Error('番茄：公开正文暂不可用，请稍后刷新本章');}
    var body=json&&json.data;
    if(!json||json.success!==true||!body)throw new Error('番茄：公开正文未收录本章或暂不可用，请稍后重试');
    if(fqString(body.gid)!==id)throw new Error('番茄：公开正文章节标识不一致，已停止读取');
    if(!fqString(data.title).trim()||fqString(body.title).trim()!==fqString(data.title).trim())throw new Error('番茄：公开正文标题与目录不一致，已停止读取');
    var content=fqBodyContent(body.content,false);
    if(/[\uE000-\uF8FF]/.test(content))throw new Error('番茄：公开正文出现未知字体编码，请更新书源');
